package com.aoo.bcg.poker;
import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class ShengJiEngineTest{@Test void enforcesFollowSuitTrumpWinnerAndDefenderPoints(){var config=new ShengJiConfig(2,7,4);var state=new ShengJiState(Map.of(0,List.of(105),1,List.of(110,210),2,List.of(205),3,List.of(113)),0,0,0,Map.of(),0,false);var engine=new ShengJiEngine();state=engine.play(state,0,105,config);var afterLead=state;assertThrows(IllegalStateException.class,()->engine.play(afterLead,1,210,config));state=engine.play(state,1,110,config);state=engine.play(state,2,205,config);state=engine.play(state,3,113,config);assertEquals(2,state.currentSeat());assertEquals(0,state.defenderPoints());assertTrue(state.trick().isEmpty());assertFalse(state.finished());}}
